const inItem = $input.first().json;
const body = inItem.body || inItem;
if (!body || !body.data || !Array.isArray(body.data.fields)) {
  throw new Error('invalid_tally_payload: missing data.fields');
}
const data = body.data;
const byLabel = {};
for (const f of data.fields) {
  if (f.label) byLabel[f.label] = f.value;
}
const pick = (k) => {
  const v = byLabel[k];
  if (Array.isArray(v)) return v.length ? String(v[0]) : '';
  return v == null ? '' : String(v);
};
const pickJoin = (k) => {
  const v = byLabel[k];
  if (Array.isArray(v)) return v.join(', ');
  return v == null ? '' : String(v);
};
const hubspot_id = pick('hubspot_id').trim();
const submission_id = data.submissionId || data.responseId;
if (!submission_id) throw new Error('missing_submission_id');
return { json: {
  submission_id,
  tally_form_id: data.formId || '',
  submitted_at: body.createdAt || new Date().toISOString(),
  hubspot_id,
  has_hubspot_id: hubspot_id.length > 0,
  email_prefill: pick('email_prefill').trim(),
  shop_name: pick('Shop name'),
  entity_name: pick('Entity name (optional)'),
  delivery_address: pick('Delivery address'),
  manager_name: pick('Manger/owner name'),
  form_email: pick('Email'),
  form_phone: pick('Phone'),
  account_contact: pick('Account contact?'),
  account_name: pick('Account name'),
  account_email: pick('Account email'),
  account_phone: pick('Account phone'),
  payment_term_selection: pick('Payments'),
  legal_entity: pick('Legal entity name'),
  abn_acn: pick('ABN / ACN'),
  credit_term: pickJoin('Credit term  '),
  credit_limit: pick('Credit limit'),
  raw_payload_json: JSON.stringify(body)
} };

const resp = $input.first().json;
const results = (resp && resp.results) || [];
const contact_ids = results.map(r => String(r.toObjectId || (r.to && r.to.id) || r.id || '')).filter(Boolean);
return { json: { contact_ids, has_contacts: contact_ids.length > 0 } };

const batchResp = $input.first().json;
const v = $('Validate & Normalize').item.json;
const company = $('HubSpot Get Company').item.json;
const contacts = (batchResp && batchResp.results) || [];
const formEmail = (v.form_email || '').toLowerCase().trim();
const matchingContact = contacts.find(function(c){
  const e = ((c.properties && c.properties.email) || '').toLowerCase().trim();
  return e && e === formEmail;
});
const forwardGuardOk = !!matchingContact;
return { json: {
  matched_via: forwardGuardOk ? 'hubspot_id' : 'hubspot_id_disputed',
  hubspot_company_id: String(company.id || ''),
  matched_company_name: (company.properties && company.properties.name) || '',
  forward_guard_flag: !forwardGuardOk,
  forward_guard_checked_contacts: contacts.length
} };

const company = $('HubSpot Get Company').item.json;
return { json: {
  matched_via: 'hubspot_id_disputed',
  hubspot_company_id: String(company.id || ''),
  matched_company_name: (company.properties && company.properties.name) || '',
  forward_guard_flag: true,
  forward_guard_checked_contacts: 0
} };

return { json: {
  matched_via: 'invalid_id',
  hubspot_company_id: '',
  matched_company_name: '',
  forward_guard_flag: false
} };

const m = $input.first().json;
const v = $('Validate & Normalize').item.json;
const now = new Date().toISOString();
const airtable_body = {
  records: [{
    fields: {
      submission_id: v.submission_id,
      tally_form_id: v.tally_form_id,
      submitted_at: v.submitted_at,
      hubspot_company_id: m.hubspot_company_id || '',
      matched_via: m.matched_via,
      forward_guard_flag: !!m.forward_guard_flag,
      shop_name: v.shop_name,
      entity_name: v.entity_name,
      abn: v.abn_acn,
      delivery_address: v.delivery_address,
      form_email: v.form_email,
      form_phone: v.form_phone,
      account_contact_name: v.account_name,
      account_contact_email: v.account_email,
      account_contact_phone: v.account_phone,
      payment_term_selection: v.payment_term_selection,
      raw_payload_json: v.raw_payload_json,
      status: 'under review',
      created_at: now,
      updated_at: now
    }
  }],
  typecast: true
};
return { json: {
  airtable_body_str: JSON.stringify(airtable_body),
  matched_via: m.matched_via,
  hubspot_company_id: m.hubspot_company_id || '',
  forward_guard_flag: !!m.forward_guard_flag,
  matched_company_name: m.matched_company_name || ''
} };

const v = $('Validate & Normalize').item.json;
const p = $('Prepare Airtable Body').item.json;
const created = $('Create Airtable Submission').item.json;
const recordId = (created.records && created.records[0] && created.records[0].id) || '';

const matchEmoji = {
  'hubspot_id': ':white_check_mark: HubSpot ID 매칭',
  'hubspot_id_disputed': ':warning: forward 가드 의심 (email 불일치)',
  'invalid_id': ':x: HubSpot Company 찾을 수 없음 (invalid ID)',
  'lookup_error': ':rotating_light: HubSpot 조회 에러',
  'unmatched': ':grey_question: 매칭 실패 (영업 판단 필요)'
}[p.matched_via] || `:question: ${p.matched_via}`;

const lines = [
  `*온보딩 폼 제출* — ${v.shop_name || '(상호 미입력)'}`,
  matchEmoji,
  p.matched_company_name ? `HubSpot Company: *${p.matched_company_name}* (id ${p.hubspot_company_id})` : null,
  `Email: ${v.form_email} · Phone: ${v.form_phone}`,
  `Payment: *${v.payment_term_selection || '(미선택)'}*${v.payment_term_selection === 'Credit application' ? ` · Term: ${v.credit_term} · Limit: ${v.credit_limit}` : ''}`,
  v.legal_entity ? `Legal entity: ${v.legal_entity} · ABN/ACN: ${v.abn_acn}` : null,
  `Airtable: https://airtable.com/appag4IfzpTeQPS1X/tblWrkl7mDixzbpTK/${recordId}`,
  p.hubspot_company_id ? `HubSpot: https://app.hubspot.com/contacts/_/company/${p.hubspot_company_id}` : null
].filter(Boolean);

return { json: { slack_text: lines.join('\n'), airtable_record_id: recordId } };
